#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>
#include <ctype.h>

#define MAX_CLIENTS 64
#define BUFFER_SIZE 8192
#define MAX_HEADERS 32

typedef struct {
    int fd;
    char nick[32];
    int authenticated;
} client_t;

static client_t clients[MAX_CLIENTS];
static pthread_mutex_t clients_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    char method[16];
    char path[256];
    char headers[MAX_HEADERS][2][256];
    int header_count;
    char *body;
    size_t body_len;
    size_t content_length;
    int has_content_length;
    int has_transfer_encoding;
    int chunked;
} http_request_t;

static int parse_chunk_size(const char *line) {
    long size = 0;
    while (*line && *line != '\r' && *line != ';') {
        char c = tolower(*line);
        size <<= 4;
        if (c >= '0' && c <= '9') size += c - '0';
        else if (c >= 'a' && c <= 'f') size += c - 'a' + 10;
        else return -1;
        /* Reject absurdly large chunk sizes to avoid integer overflow */
        if (size > (long)BUFFER_SIZE) return -1;
        line++;
    }
    return (int)size;
}

static size_t determine_body_length(http_request_t *req) {
    /* RFC 7230 Section 3.3.3: If Transfer-Encoding is present,
     * Content-Length MUST be ignored. Transfer-Encoding always
     * takes precedence regardless of header ordering. */
    if (req->has_transfer_encoding) {
        /* TE always wins per RFC 7230 - ignore Content-Length */
        req->has_content_length = 0;
        return 0; /* will use chunked */
    }
    if (req->has_content_length) return req->content_length;
    return 0;
}

static int parse_request(const char *raw, size_t raw_len, http_request_t *req) {
    memset(req, 0, sizeof(*req));
    const char *p = raw;
    const char *end = raw + raw_len;

    /* Parse request line */
    const char *sp1 = strchr(p, ' ');
    if (!sp1) return -1;
    size_t mlen = sp1 - p;
    if (mlen >= sizeof(req->method)) return -1;
    memcpy(req->method, p, mlen);
    req->method[mlen] = '\0';
    p = sp1 + 1;

    const char *sp2 = strchr(p, ' ');
    if (!sp2) return -1;
    size_t plen = sp2 - p;
    if (plen >= sizeof(req->path)) return -1;
    memcpy(req->path, p, plen);
    req->path[plen] = '\0';

    const char *eol = strstr(p, "\r\n");
    if (!eol) return -1;
    p = eol + 2;

    /* Parse headers */
    while (p < end && *p != '\r') {
        if (req->header_count >= MAX_HEADERS) return -1;
        const char *colon = strchr(p, ':');
        eol = strstr(p, "\r\n");
        if (!colon || !eol || colon > eol) return -1;

        size_t nlen = colon - p;
        if (nlen >= 256) return -1;
        memcpy(req->headers[req->header_count][0], p, nlen);
        req->headers[req->header_count][0][nlen] = '\0';

        const char *val = colon + 1;
        while (*val == ' ') val++;
        size_t vlen = eol - val;
        if (vlen >= 256) return -1;
        memcpy(req->headers[req->header_count][1], val, vlen);
        req->headers[req->header_count][1][vlen] = '\0';

        if (strcasecmp(req->headers[req->header_count][0], "Content-Length") == 0) {
            req->content_length = (size_t)atol(req->headers[req->header_count][1]);
            req->has_content_length = 1;
        }
        if (strcasecmp(req->headers[req->header_count][0], "Transfer-Encoding") == 0) {
            if (strcasecmp(req->headers[req->header_count][1], "chunked") == 0) {
                req->has_transfer_encoding = 1;
                req->chunked = 1;
            }
        }

        req->header_count++;
        p = eol + 2;
    }

    if (p < end && *p == '\r') p += 2; /* skip blank line */

    size_t body_length = determine_body_length(req);

    if (req->chunked) {
        /* Dechunk the body */
        char *decoded = malloc(BUFFER_SIZE);
        if (!decoded) return -1;
        size_t decoded_len = 0;
        while (p < end) {
            int chunk_sz = parse_chunk_size(p);
            if (chunk_sz <= 0) break;
            eol = strstr(p, "\r\n");
            if (!eol) break;
            p = eol + 2;
            if (p + chunk_sz > end) break;
            /* Bounds check against the fixed decode buffer to prevent heap overflow */
            if (decoded_len + (size_t)chunk_sz > BUFFER_SIZE) break;
            memcpy(decoded + decoded_len, p, chunk_sz);
            decoded_len += chunk_sz;
            p += chunk_sz + 2;
        }
        req->body = decoded;
        req->body_len = decoded_len;
    } else if (body_length > 0) {
        req->body = malloc(body_length + 1);
        if (!req->body) return -1;
        size_t avail = end - p;
        size_t copy = avail < body_length ? avail : body_length;
        memcpy(req->body, p, copy);
        req->body[copy] = '\0';
        req->body_len = copy;
    }

    return 0;
}

static void handle_chat_message(int client_fd, http_request_t *req) {
    if (req->body && req->body_len > 0) {
        pthread_mutex_lock(&clients_lock);
        for (int i = 0; i < MAX_CLIENTS; i++) {
            if (clients[i].fd > 0 && clients[i].fd != client_fd) {
                send(clients[i].fd, req->body, req->body_len, MSG_NOSIGNAL);
            }
        }
        pthread_mutex_unlock(&clients_lock);
    }
    const char *resp = "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nOK";
    send(client_fd, resp, strlen(resp), 0);
}

static void *client_handler(void *arg) {
    int fd = *(int *)arg;
    free(arg);
    char buf[BUFFER_SIZE];

    while (1) {
        ssize_t n = recv(fd, buf, sizeof(buf) - 1, 0);
        if (n <= 0) break;
        buf[n] = '\0';

        http_request_t req;
        if (parse_request(buf, n, &req) == 0) {
            if (strcmp(req.path, "/chat/send") == 0) {
                handle_chat_message(fd, &req);
            }
            if (req.body) free(req.body);
        }
    }
    close(fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    int port = argc > 1 ? atoi(argv[1]) : 8080;
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(port), .sin_addr.s_addr = INADDR_ANY};
    bind(server_fd, (struct sockaddr *)&addr, sizeof(addr));
    listen(server_fd, 128);

    printf("Chat server on port %d\n", port);
    while (1) {
        int *cfd = malloc(sizeof(int));
        if (!cfd) continue;
        *cfd = accept(server_fd, NULL, NULL);
        if (*cfd < 0) { free(cfd); continue; }
        pthread_t t;
        pthread_create(&t, NULL, client_handler, cfd);
        pthread_detach(t);
    }
}
